//! Normalised baseline schema statements before domain table moves.

pub(super) const BASELINE: &[&str] = &[
    "CREATE INDEX IF NOT EXISTS bank_transactions_account ON bank_transactions (bank_number, id);",
    "CREATE INDEX IF NOT EXISTS coin_prices_coin ON coin_prices (coin_id, id);",
    "CREATE INDEX IF NOT EXISTS coins_creator ON coins (creator_user, id);",
    "CREATE INDEX IF NOT EXISTS computer_hardware_computer ON computer_hardware (computer_id, kind, id);",
    "CREATE INDEX IF NOT EXISTS computer_ports_service ON computer_ports (computer_id, service);",
    "CREATE INDEX IF NOT EXISTS computer_saved_networks_computer ON computer_saved_networks (computer_id, id);",
    "CREATE INDEX IF NOT EXISTS computer_sessions_computer ON computer_sessions (computer_id, id);",
    "CREATE INDEX IF NOT EXISTS computer_users_password ON computer_users (password_hash);",
    "CREATE INDEX IF NOT EXISTS computer_users_person ON computer_users (person_id);",
    "CREATE INDEX IF NOT EXISTS computers_local_ip ON computers (local_ip);",
    "CREATE INDEX IF NOT EXISTS computers_network ON computers (network_id, local_ip);",
    "CREATE INDEX IF NOT EXISTS computers_router ON computers (router_id);",
    "CREATE INDEX IF NOT EXISTS ctf_events_creator ON ctf_events (creator_id, name);",
    "CREATE INDEX IF NOT EXISTS email_replies_thread ON email_replies (email_id, id);",
    "CREATE INDEX IF NOT EXISTS emails_inbox ON emails (address, id);",
    "CREATE INDEX IF NOT EXISTS flood_subscribers_computer ON flood_subscribers (computer_id, origin);",
    "CREATE INDEX IF NOT EXISTS library_exploits_library ON library_exploits (library_id, id);",
    "CREATE INDEX IF NOT EXISTS mining_subscribers_coin ON mining_subscribers (coin_id, id);",
    "CREATE INDEX IF NOT EXISTS mining_subscribers_computer ON mining_subscribers (computer_id);",
    "CREATE INDEX IF NOT EXISTS networks_map ON networks (map_x, map_y);",
    "CREATE INDEX IF NOT EXISTS node_libraries_library ON node_libraries (library_id);",
    "CREATE INDEX IF NOT EXISTS nodes_children ON nodes (parent_id, seq);",
    "CREATE INDEX IF NOT EXISTS offers_book ON offers (coin_id, sell, id);",
    "CREATE INDEX IF NOT EXISTS port_forwards_port ON port_forwards (port_id);",
    "CREATE INDEX IF NOT EXISTS reverse_shells_router ON reverse_shells (router_id, id);",
    "CREATE INDEX IF NOT EXISTS router_firewall_rules_router ON router_firewall_rules (router_id, id);",
    "CREATE INDEX IF NOT EXISTS routers_wifi ON routers (bssid COLLATE NOCASE, essid);",
    "CREATE INDEX IF NOT EXISTS routine_payments_subscription ON routine_payments (bank_number, kind);",
    "CREATE INDEX IF NOT EXISTS routine_service_restarts_computer ON routine_service_restarts (computer_id);",
    "CREATE INDEX IF NOT EXISTS routines_due ON routines (at, id);",
    "CREATE INDEX IF NOT EXISTS saved_library_versions_kind ON saved_library_versions (kind, id);",
    "CREATE INDEX IF NOT EXISTS sniffer_subscribers_router ON sniffer_subscribers (router_id, id);",
    "CREATE INDEX IF NOT EXISTS wallet_balances_coin ON wallet_balances (coin_id);",
    "CREATE TABLE IF NOT EXISTS active_traces ( id INTEGER PRIMARY KEY AUTOINCREMENT, computer_id INTEGER NOT NULL REFERENCES computers(id) ON DELETE CASCADE, admin_id INTEGER NOT NULL REFERENCES persons(id) ON DELETE CASCADE, terminal INTEGER NOT NULL, ends_at INTEGER NOT NULL );",
    "CREATE TABLE IF NOT EXISTS bank_accounts ( number TEXT PRIMARY KEY, password_hash TEXT NOT NULL REFERENCES passwords(hash), money REAL NOT NULL );",
    "CREATE TABLE IF NOT EXISTS bank_subscription_networks ( bank_number TEXT NOT NULL REFERENCES bank_accounts(number) ON DELETE CASCADE, kind INTEGER NOT NULL, seq INTEGER NOT NULL, public_ip TEXT NOT NULL, PRIMARY KEY (bank_number, kind, seq) );",
    "CREATE TABLE IF NOT EXISTS bank_subscriptions ( bank_number TEXT NOT NULL REFERENCES bank_accounts(number) ON DELETE CASCADE, kind INTEGER NOT NULL, amount INTEGER NOT NULL, next_payment_at INTEGER NOT NULL, PRIMARY KEY (bank_number, kind) );",
    "CREATE TABLE IF NOT EXISTS bank_transactions ( id INTEGER PRIMARY KEY AUTOINCREMENT, bank_number TEXT NOT NULL REFERENCES bank_accounts(number) ON DELETE CASCADE, account TEXT NOT NULL, amount INTEGER NOT NULL, reason TEXT NOT NULL, date TEXT NOT NULL, success INTEGER NOT NULL );",
    "CREATE TABLE IF NOT EXISTS coin_pending_trades ( coin_id INTEGER PRIMARY KEY REFERENCES coins(id) ON DELETE CASCADE, value INTEGER NOT NULL, amount INTEGER NOT NULL );",
    "CREATE TABLE IF NOT EXISTS coin_prices ( id INTEGER PRIMARY KEY, coin_id INTEGER NOT NULL REFERENCES coins(id) ON DELETE CASCADE, price REAL NOT NULL, date TEXT NOT NULL );",
    "CREATE TABLE IF NOT EXISTS coins ( id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT NOT NULL UNIQUE, creator_user TEXT NOT NULL, creator_password_hash TEXT NOT NULL REFERENCES passwords(hash), address TEXT NOT NULL, mining_cycle REAL NOT NULL, reward REAL NOT NULL, mined_coins REAL NOT NULL, max_supply REAL NOT NULL, price REAL NOT NULL, last_cycle_at INTEGER );",
    "CREATE TABLE IF NOT EXISTS company_market ( network_id INTEGER PRIMARY KEY REFERENCES networks(id) ON DELETE CASCADE, seed INTEGER, ddos_until INTEGER NOT NULL DEFAULT 0 );",
    "CREATE TABLE IF NOT EXISTS company_shares ( id INTEGER PRIMARY KEY AUTOINCREMENT, network_id INTEGER NOT NULL REFERENCES networks(id) ON DELETE CASCADE, bank_account TEXT NOT NULL, shares INTEGER NOT NULL, UNIQUE (network_id, bank_account) );",
    "CREATE TABLE IF NOT EXISTS computer_hardware ( id INTEGER PRIMARY KEY, computer_id INTEGER NOT NULL REFERENCES computers(id) ON DELETE CASCADE, kind INTEGER NOT NULL, hardware_id INTEGER NOT NULL, health REAL NOT NULL );",
    "CREATE TABLE IF NOT EXISTS computer_net_cards ( computer_hardware_id INTEGER PRIMARY KEY REFERENCES computer_hardware(id) ON DELETE CASCADE, active INTEGER NOT NULL, monitor_enabled INTEGER NOT NULL );",
    "CREATE TABLE IF NOT EXISTS computer_ports ( id INTEGER PRIMARY KEY, computer_id INTEGER NOT NULL REFERENCES computers(id) ON DELETE CASCADE, number INTEGER NOT NULL, service INTEGER NOT NULL, library_id INTEGER NOT NULL REFERENCES libraries(id), closed INTEGER NOT NULL, visible INTEGER NOT NULL, UNIQUE (computer_id, number) );",
    "CREATE TABLE IF NOT EXISTS computer_processes ( computer_id INTEGER NOT NULL REFERENCES computers(id) ON DELETE CASCADE, pid INTEGER NOT NULL, user TEXT NOT NULL, name TEXT NOT NULL, cpu REAL NOT NULL, ram_mb REAL NOT NULL, protected INTEGER NOT NULL, service INTEGER, terminal INTEGER NOT NULL, PRIMARY KEY (computer_id, pid) );",
    "CREATE TABLE IF NOT EXISTS computer_saved_networks ( id INTEGER PRIMARY KEY, computer_id INTEGER NOT NULL REFERENCES computers(id) ON DELETE CASCADE, bssid TEXT NOT NULL, essid TEXT NOT NULL, password_hash TEXT NOT NULL REFERENCES passwords(hash), public_ip TEXT NOT NULL );",
    "CREATE TABLE IF NOT EXISTS computer_sessions ( id INTEGER PRIMARY KEY, computer_id INTEGER NOT NULL REFERENCES computers(id) ON DELETE CASCADE, user TEXT NOT NULL );",
    "CREATE TABLE IF NOT EXISTS computer_users ( id INTEGER PRIMARY KEY, computer_id INTEGER NOT NULL REFERENCES computers(id) ON DELETE CASCADE, name TEXT NOT NULL, password_hash TEXT NOT NULL REFERENCES passwords(hash), person_id INTEGER REFERENCES persons(id) ON DELETE SET NULL, deletable INTEGER NOT NULL, UNIQUE (computer_id, name) );",
    "CREATE TABLE IF NOT EXISTS computers ( id INTEGER PRIMARY KEY AUTOINCREMENT, kind INTEGER NOT NULL, network_id INTEGER NOT NULL REFERENCES networks(id) ON DELETE CASCADE, parent_id INTEGER REFERENCES computers(id) ON DELETE CASCADE, parent_seq INTEGER, router_id INTEGER REFERENCES computers(id) ON DELETE SET NULL, gateway TEXT NOT NULL DEFAULT '', name TEXT NOT NULL, -- empty for a hub, which has no address local_ip TEXT NOT NULL, next_pid INTEGER NOT NULL, reboot_end INTEGER NOT NULL DEFAULT 0, -- whether it can't be reached whatever the time (`LanPcInfo.isHidden`) hidden INTEGER NOT NULL DEFAULT 0, -- the NPC whose smartphone it is (`LanPcInfo.npcOwner`), which can't be reached while the NPC isn't at work npc_owner INTEGER REFERENCES persons(id) ON DELETE SET NULL, -- the kind of network it was made for (`Computer.tipoRed`), which stays when it joins another network network_kind INTEGER NOT NULL, -- player home network used for Ethernet (`PlayerConfigOS.rentalHomeIP`) rental_home_ip TEXT NOT NULL DEFAULT '', UNIQUE (parent_id, parent_seq) );",
    "CREATE TABLE IF NOT EXISTS cpus ( id INTEGER PRIMARY KEY, name TEXT NOT NULL, quality INTEGER NOT NULL, required_power REAL NOT NULL, speed REAL NOT NULL, cores INTEGER NOT NULL, socket TEXT NOT NULL, UNIQUE (name, quality, required_power, speed, cores, socket) );",
    "CREATE TABLE IF NOT EXISTS crown_shield_networks ( public_ip TEXT PRIMARY KEY, guild_name TEXT NOT NULL UNIQUE );",
    "CREATE TABLE IF NOT EXISTS crown_state ( id INTEGER PRIMARY KEY CHECK (id = 0), candidate TEXT NOT NULL, since INTEGER NOT NULL );",
    "CREATE TABLE IF NOT EXISTS ctf_accounts ( person_id INTEGER PRIMARY KEY REFERENCES persons(id) ON DELETE CASCADE, user TEXT NOT NULL UNIQUE, password_hash TEXT NOT NULL REFERENCES passwords(hash) );",
    "CREATE TABLE IF NOT EXISTS ctf_events ( name TEXT PRIMARY KEY, creator_id INTEGER NOT NULL REFERENCES persons(id) ON DELETE CASCADE, user TEXT NOT NULL, password_hash TEXT NOT NULL REFERENCES passwords(hash), description TEXT NOT NULL, public_address TEXT NOT NULL, creator_name TEXT NOT NULL, mail_content TEXT NOT NULL, -- rating sums and vote count;",
    "CREATE TABLE IF NOT EXISTS ctf_players ( event_name TEXT NOT NULL REFERENCES ctf_events(name) ON DELETE CASCADE, person_id INTEGER NOT NULL REFERENCES persons(id) ON DELETE CASCADE, completed INTEGER NOT NULL, quality_rate INTEGER NOT NULL DEFAULT 0, difficulty_rate INTEGER NOT NULL DEFAULT 0, PRIMARY KEY (event_name, person_id) );",
    "CREATE TABLE IF NOT EXISTS debug_libraries ( node_id INTEGER PRIMARY KEY REFERENCES nodes(id) ON DELETE CASCADE, patch_seed INTEGER, auto_patch_at INTEGER, num_patches INTEGER NOT NULL DEFAULT 0 );",
    "CREATE TABLE IF NOT EXISTS zero_day_state ( id INTEGER PRIMARY KEY, state TEXT NOT NULL );",
    "CREATE TABLE IF NOT EXISTS email_replies ( id INTEGER PRIMARY KEY AUTOINCREMENT, email_id INTEGER NOT NULL REFERENCES emails(id) ON DELETE CASCADE, body TEXT NOT NULL );",
    "CREATE TABLE IF NOT EXISTS emails ( id INTEGER PRIMARY KEY AUTOINCREMENT, address TEXT NOT NULL REFERENCES mail_accounts(address) ON DELETE CASCADE, sender TEXT NOT NULL, subject TEXT NOT NULL, body TEXT NOT NULL );",
    "CREATE TABLE IF NOT EXISTS flood_subscribers ( id INTEGER PRIMARY KEY AUTOINCREMENT, computer_id INTEGER NOT NULL REFERENCES computers(id) ON DELETE CASCADE, origin TEXT NOT NULL, counted INTEGER NOT NULL );",
    "CREATE TABLE IF NOT EXISTS gpus ( id INTEGER PRIMARY KEY, name TEXT NOT NULL, quality INTEGER NOT NULL, required_power REAL NOT NULL, hashrate REAL NOT NULL, UNIQUE (name, quality, required_power, hashrate) );",
    "CREATE TABLE IF NOT EXISTS guild_admin_absences ( guild_id INTEGER NOT NULL REFERENCES guilds(id) ON DELETE CASCADE, network_id INTEGER NOT NULL REFERENCES networks(id) ON DELETE CASCADE, percent INTEGER NOT NULL, recovery_day INTEGER, recovering INTEGER NOT NULL, PRIMARY KEY (guild_id, network_id) );",
    "CREATE TABLE IF NOT EXISTS guild_admin_restore_disabled ( guild_id INTEGER NOT NULL REFERENCES guilds(id) ON DELETE CASCADE, network_id INTEGER NOT NULL REFERENCES networks(id) ON DELETE CASCADE, PRIMARY KEY (guild_id, network_id) );",
    "CREATE TABLE IF NOT EXISTS guild_companies ( guild_id INTEGER NOT NULL REFERENCES guilds(id) ON DELETE CASCADE, network_id INTEGER NOT NULL REFERENCES networks(id) ON DELETE CASCADE, PRIMARY KEY (guild_id, network_id) );",
    "CREATE TABLE IF NOT EXISTS guilds ( id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT NOT NULL UNIQUE, bank_account TEXT NOT NULL, total_exp INTEGER NOT NULL DEFAULT 0, investment_perks INTEGER NOT NULL DEFAULT 0, admin_restore_perks INTEGER NOT NULL DEFAULT 0, has_crown INTEGER NOT NULL DEFAULT 0, crown_shield_public_ip TEXT NOT NULL DEFAULT '', player_member INTEGER NOT NULL DEFAULT 0 );",
    "CREATE TABLE IF NOT EXISTS guild_player_owners ( guild_id INTEGER PRIMARY KEY REFERENCES guilds(id) ON DELETE CASCADE );",
    "CREATE TABLE IF NOT EXISTS hard_disks ( id INTEGER PRIMARY KEY, name TEXT NOT NULL, quality INTEGER NOT NULL, required_power REAL NOT NULL, speed INTEGER NOT NULL, size_mb REAL NOT NULL, UNIQUE (name, quality, required_power, speed, size_mb) );",
    "CREATE TABLE IF NOT EXISTS libraries ( id INTEGER PRIMARY KEY AUTOINCREMENT, kind INTEGER NOT NULL, version TEXT NOT NULL, UNIQUE (kind, version) );",
    "CREATE TABLE IF NOT EXISTS library_exploit_batches ( library_id INTEGER NOT NULL REFERENCES libraries(id) ON DELETE CASCADE, hidden INTEGER NOT NULL, PRIMARY KEY (library_id, hidden) );",
    "CREATE TABLE IF NOT EXISTS library_exploits ( id INTEGER PRIMARY KEY AUTOINCREMENT, library_id INTEGER NOT NULL REFERENCES libraries(id) ON DELETE CASCADE, hidden INTEGER NOT NULL, patched INTEGER NOT NULL DEFAULT 0, zone_address TEXT NOT NULL, unsec_value TEXT NOT NULL, name TEXT NOT NULL, part TEXT NOT NULL );",
    "CREATE TABLE IF NOT EXISTS library_latest ( kind INTEGER PRIMARY KEY, library_id INTEGER NOT NULL REFERENCES libraries(id) );",
    "CREATE TABLE IF NOT EXISTS library_reporters ( player INTEGER PRIMARY KEY );",
    "CREATE TABLE IF NOT EXISTS library_weakness_uses ( kind INTEGER NOT NULL, address TEXT NOT NULL, unsec_value TEXT NOT NULL, uses INTEGER NOT NULL, PRIMARY KEY (kind, address, unsec_value) );",
    "CREATE TABLE IF NOT EXISTS library_zone_patches ( kind INTEGER NOT NULL, address TEXT NOT NULL, times_patched INTEGER NOT NULL, PRIMARY KEY (kind, address) );",
    "CREATE TABLE IF NOT EXISTS mail_accounts ( address TEXT PRIMARY KEY, password_hash TEXT NOT NULL REFERENCES passwords(hash), npc_contents INTEGER NOT NULL DEFAULT 0 );",
    "CREATE TABLE IF NOT EXISTS mail_spam ( address TEXT PRIMARY KEY REFERENCES mail_accounts(address) ON DELETE CASCADE, player_pc_id TEXT NOT NULL DEFAULT '', filter INTEGER NOT NULL DEFAULT 1, blacklist TEXT NOT NULL DEFAULT '[]' );",
    "CREATE TABLE IF NOT EXISTS memory_zones ( id INTEGER PRIMARY KEY, library_id INTEGER NOT NULL REFERENCES libraries(id) ON DELETE CASCADE, address TEXT NOT NULL, hide INTEGER NOT NULL, UNIQUE (library_id, address) );",
    "CREATE TABLE IF NOT EXISTS mining_subscribers ( id INTEGER PRIMARY KEY AUTOINCREMENT, coin_id INTEGER NOT NULL REFERENCES coins(id) ON DELETE CASCADE, subwallet_id INTEGER NOT NULL REFERENCES subwallets(id) ON DELETE CASCADE, computer_id INTEGER NOT NULL REFERENCES computers(id) ON DELETE CASCADE );",
    "CREATE TABLE IF NOT EXISTS motherboards ( id INTEGER PRIMARY KEY, name TEXT NOT NULL, quality INTEGER NOT NULL, required_power REAL NOT NULL, cpu_slots INTEGER NOT NULL, cpu_socket TEXT NOT NULL, ram_model INTEGER NOT NULL, ram_slots INTEGER NOT NULL, max_ram_mb INTEGER NOT NULL, pci_slots INTEGER NOT NULL, UNIQUE (name, quality, required_power, cpu_slots, cpu_socket, ram_model, ram_slots, max_ram_mb, pci_slots) );",
    "CREATE TABLE IF NOT EXISTS net_cards ( id INTEGER PRIMARY KEY, name TEXT NOT NULL, quality INTEGER NOT NULL, required_power REAL NOT NULL, wifi INTEGER NOT NULL, monitor_support INTEGER NOT NULL, UNIQUE (name, quality, required_power, wifi, monitor_support) );",
    "CREATE TABLE IF NOT EXISTS network_admins ( network_id INTEGER PRIMARY KEY REFERENCES networks(id) ON DELETE CASCADE, person_id INTEGER REFERENCES persons(id) ON DELETE SET NULL, intelligence INTEGER NOT NULL, pc_experience INTEGER NOT NULL, work_performance INTEGER NOT NULL, dead_or_fired INTEGER NOT NULL );",
    "CREATE TABLE IF NOT EXISTS network_library_updates ( network_id INTEGER NOT NULL REFERENCES networks(id) ON DELETE CASCADE, kind INTEGER NOT NULL, library_id INTEGER NOT NULL REFERENCES libraries(id), PRIMARY KEY (network_id, kind) );",
    "CREATE TABLE IF NOT EXISTS network_library_choices ( network_id INTEGER NOT NULL REFERENCES networks(id) ON DELETE CASCADE, kind INTEGER NOT NULL, library_id INTEGER NOT NULL REFERENCES libraries(id), PRIMARY KEY (network_id, kind) );",
    "CREATE TABLE IF NOT EXISTS networks ( id INTEGER PRIMARY KEY AUTOINCREMENT, kind INTEGER NOT NULL, public_ip TEXT NOT NULL UNIQUE, domain TEXT NOT NULL COLLATE NOCASE, contact_name TEXT, contact_mail TEXT, contact_phone TEXT, map_x REAL NOT NULL, map_y REAL NOT NULL, -- whether its LAN was generated as the game generates one, which its administrator restores it to has_plan INTEGER NOT NULL DEFAULT 0, -- disabled for not having been paid for (`NetworkLan.disabledNetwork`) disabled INTEGER NOT NULL DEFAULT 0, -- the router's home-network marker (`RouterConfigOS.isHomeNetwork`) home INTEGER NOT NULL DEFAULT 0, -- its connection speed, one of the ISP's packs (`NetworkLan.netSpeed`) net_speed INTEGER NOT NULL DEFAULT 6, -- the address its NPCs' starter mission mail names, set when a mission was placed in it -- (`NetworkLan.missionCreated`;",
    "CREATE TABLE IF NOT EXISTS node_commands ( node_id INTEGER PRIMARY KEY REFERENCES nodes(id) ON DELETE CASCADE, command INTEGER NOT NULL );",
    "CREATE TABLE IF NOT EXISTS node_libraries ( node_id INTEGER PRIMARY KEY REFERENCES nodes(id) ON DELETE CASCADE, library_id INTEGER NOT NULL REFERENCES libraries(id) );",
    "CREATE TABLE IF NOT EXISTS nodes ( id INTEGER PRIMARY KEY AUTOINCREMENT, computer_id INTEGER NOT NULL REFERENCES computers(id) ON DELETE CASCADE, parent_id INTEGER REFERENCES nodes(id) ON DELETE CASCADE, path TEXT NOT NULL, -- order among the parent's children;",
    "CREATE TABLE IF NOT EXISTS npcs ( person_id INTEGER PRIMARY KEY REFERENCES persons(id) ON DELETE CASCADE, user_id INTEGER NOT NULL UNIQUE REFERENCES computer_users(id) ON DELETE CASCADE, online INTEGER NOT NULL, has_rumor INTEGER NOT NULL DEFAULT 0, dead_at INTEGER, job_role INTEGER NOT NULL DEFAULT 0, license_plate TEXT, fired INTEGER NOT NULL DEFAULT 0, hire_time INTEGER, forced_login_until INTEGER, schedule_work1_start INTEGER NOT NULL, schedule_work2_start INTEGER NOT NULL, walk_to_appliance INTEGER NOT NULL, wake_up_time INTEGER, late_strikes INTEGER NOT NULL DEFAULT 0, day_alarm INTEGER NOT NULL DEFAULT 0, alarm_hour INTEGER NOT NULL DEFAULT 0, alarm_minute INTEGER NOT NULL DEFAULT 0, alarm_modified INTEGER NOT NULL DEFAULT 0, alarm_deleted INTEGER NOT NULL DEFAULT 0, work_performance INTEGER NOT NULL DEFAULT 2, company_align INTEGER NOT NULL DEFAULT 0, day_zero_contact TEXT, zero_day_index INTEGER );",
    "CREATE TABLE IF NOT EXISTS offers ( id INTEGER PRIMARY KEY, coin_id INTEGER NOT NULL REFERENCES coins(id) ON DELETE CASCADE, wallet_id INTEGER NOT NULL REFERENCES wallets(id) ON DELETE CASCADE, subwallet TEXT NOT NULL, sell INTEGER NOT NULL, price REAL NOT NULL, amount REAL NOT NULL, UNIQUE (coin_id, wallet_id) );",
    "CREATE TABLE IF NOT EXISTS passive_traces ( id INTEGER PRIMARY KEY AUTOINCREMENT, computer_id INTEGER NOT NULL UNIQUE REFERENCES computers(id) ON DELETE CASCADE );",
    "CREATE TABLE IF NOT EXISTS passwords ( hash TEXT PRIMARY KEY, plain TEXT NOT NULL );",
    "CREATE TABLE IF NOT EXISTS persons ( id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT NOT NULL, surname TEXT NOT NULL, gender INTEGER NOT NULL, mail_address TEXT REFERENCES mail_accounts(address) ON DELETE SET NULL, bank_number TEXT REFERENCES bank_accounts(number) ON DELETE SET NULL );",
    "CREATE TABLE IF NOT EXISTS player_coupons ( computer_id INTEGER PRIMARY KEY REFERENCES computers(id) ON DELETE CASCADE, coupons INTEGER NOT NULL );",
    "CREATE TABLE IF NOT EXISTS port_forwards ( router_id INTEGER NOT NULL REFERENCES routers(computer_id) ON DELETE CASCADE, number INTEGER NOT NULL, port_id INTEGER NOT NULL REFERENCES computer_ports(id) ON DELETE CASCADE, PRIMARY KEY (router_id, number) );",
    "CREATE TABLE IF NOT EXISTS power_supplies ( id INTEGER PRIMARY KEY, name TEXT NOT NULL, quality INTEGER NOT NULL, power INTEGER NOT NULL, UNIQUE (name, quality, power) );",
    "CREATE TABLE IF NOT EXISTS rams ( id INTEGER PRIMARY KEY, name TEXT NOT NULL, quality INTEGER NOT NULL, required_power REAL NOT NULL, memory_mb INTEGER NOT NULL, model INTEGER NOT NULL, UNIQUE (name, quality, required_power, memory_mb, model) );",
    "CREATE TABLE IF NOT EXISTS rental_admins ( network_id INTEGER PRIMARY KEY REFERENCES networks(id) ON DELETE CASCADE, person_id INTEGER NOT NULL REFERENCES persons(id) ON DELETE CASCADE );",
    "CREATE TABLE IF NOT EXISTS repositories ( address TEXT PRIMARY KEY );",
    "CREATE TABLE IF NOT EXISTS repository_packages ( id INTEGER PRIMARY KEY, address TEXT NOT NULL REFERENCES repositories(address) ON DELETE CASCADE, name TEXT NOT NULL, description TEXT NOT NULL, library INTEGER, UNIQUE (address, name) );",
    "CREATE TABLE IF NOT EXISTS reverse_shells ( id INTEGER PRIMARY KEY, router_id INTEGER NOT NULL REFERENCES routers(computer_id) ON DELETE CASCADE, computer_id INTEGER NOT NULL, pid INTEGER NOT NULL, port INTEGER NOT NULL, user TEXT NOT NULL, created_at INTEGER NOT NULL, FOREIGN KEY (computer_id, pid) REFERENCES computer_processes(computer_id, pid) ON DELETE CASCADE );",
    "CREATE TABLE IF NOT EXISTS router_firewall_rules ( id INTEGER PRIMARY KEY, router_id INTEGER NOT NULL REFERENCES routers(computer_id) ON DELETE CASCADE, allow INTEGER NOT NULL, port INTEGER, source TEXT, destination TEXT );",
    "CREATE TABLE IF NOT EXISTS routers ( computer_id INTEGER PRIMARY KEY REFERENCES computers(id) ON DELETE CASCADE, essid TEXT, bssid TEXT, wifi_password_hash TEXT NOT NULL REFERENCES passwords(hash), firewall_active INTEGER NOT NULL );",
    "CREATE TABLE IF NOT EXISTS routine_active_traces ( routine_id INTEGER PRIMARY KEY REFERENCES routines(id) ON DELETE CASCADE, trace_id INTEGER NOT NULL UNIQUE REFERENCES active_traces(id) ON DELETE CASCADE );",
    "CREATE TABLE IF NOT EXISTS routine_library_checks ( routine_id INTEGER PRIMARY KEY REFERENCES routines(id) ON DELETE CASCADE );",
    "CREATE TABLE IF NOT EXISTS routine_daily_upkeep ( routine_id INTEGER PRIMARY KEY REFERENCES routines(id) ON DELETE CASCADE );",
    "CREATE TABLE IF NOT EXISTS routine_mining_rounds ( routine_id INTEGER PRIMARY KEY REFERENCES routines(id) ON DELETE CASCADE, coin_id INTEGER NOT NULL UNIQUE REFERENCES coins(id) ON DELETE CASCADE );",
    "CREATE TABLE IF NOT EXISTS routine_npc_switches ( routine_id INTEGER PRIMARY KEY REFERENCES routines(id) ON DELETE CASCADE, npc_id INTEGER NOT NULL UNIQUE REFERENCES npcs(person_id) ON DELETE CASCADE );",
    "CREATE TABLE IF NOT EXISTS routine_passive_traces ( routine_id INTEGER PRIMARY KEY REFERENCES routines(id) ON DELETE CASCADE );",
    "CREATE TABLE IF NOT EXISTS routine_payments ( routine_id INTEGER PRIMARY KEY REFERENCES routines(id) ON DELETE CASCADE, bank_number TEXT NOT NULL, kind INTEGER NOT NULL );",
    "CREATE TABLE IF NOT EXISTS routine_service_restarts ( routine_id INTEGER PRIMARY KEY REFERENCES routines(id) ON DELETE CASCADE, computer_id INTEGER NOT NULL REFERENCES computers(id) ON DELETE CASCADE, service INTEGER NOT NULL );",
    "CREATE TABLE IF NOT EXISTS routines ( id INTEGER PRIMARY KEY AUTOINCREMENT, at INTEGER NOT NULL, kind TEXT NOT NULL );",
    "CREATE TABLE IF NOT EXISTS saved_library_versions ( id INTEGER PRIMARY KEY AUTOINCREMENT, kind INTEGER NOT NULL, library_id INTEGER NOT NULL REFERENCES libraries(id) ON DELETE CASCADE );",
    "CREATE TABLE IF NOT EXISTS smart_appliances ( computer_id INTEGER PRIMARY KEY REFERENCES computers(id) ON DELETE CASCADE, model TEXT NOT NULL, required_power INTEGER NOT NULL, required_temperature INTEGER NOT NULL, power INTEGER NOT NULL, temperature INTEGER NOT NULL, alarm INTEGER NOT NULL, override_enabled INTEGER NOT NULL, -- the world second its hardware works again after an accident (`SmartAppConfigOS.brokenUntil`) broken_until INTEGER NOT NULL );",
    "CREATE TABLE IF NOT EXISTS sniffer_subscribers ( id INTEGER PRIMARY KEY AUTOINCREMENT, computer_id INTEGER NOT NULL REFERENCES computers(id) ON DELETE CASCADE, router_id INTEGER REFERENCES routers(computer_id) ON DELETE CASCADE );",
    "CREATE TABLE IF NOT EXISTS subwallet_transactions ( subwallet_id INTEGER PRIMARY KEY REFERENCES subwallets(id) ON DELETE CASCADE, counterparty TEXT NOT NULL, amount REAL NOT NULL, direction INTEGER NOT NULL, date TEXT NOT NULL );",
    "CREATE TABLE IF NOT EXISTS subwallets ( id INTEGER PRIMARY KEY, coin_id INTEGER NOT NULL REFERENCES coins(id) ON DELETE CASCADE, user TEXT NOT NULL, password_hash TEXT NOT NULL REFERENCES passwords(hash), balance REAL NOT NULL, info TEXT NOT NULL, wallet_id INTEGER NOT NULL REFERENCES wallets(id) ON DELETE CASCADE, UNIQUE (coin_id, user) );",
    "CREATE TABLE IF NOT EXISTS trace_state ( id INTEGER PRIMARY KEY CHECK (id = 0), strikes INTEGER NOT NULL DEFAULT 0, token_generation INTEGER NOT NULL DEFAULT 0, passive_running INTEGER NOT NULL DEFAULT 0, stage INTEGER NOT NULL DEFAULT 0, from_ip TEXT NOT NULL DEFAULT '', to_ip TEXT NOT NULL DEFAULT '', origin_id INTEGER );",
    "CREATE TABLE IF NOT EXISTS traffic_networks ( network_id INTEGER PRIMARY KEY REFERENCES networks(id) ON DELETE CASCADE, credentials_id INTEGER REFERENCES persons(id) ON DELETE SET NULL, override_enabled INTEGER NOT NULL, override_used INTEGER NOT NULL );",
    "CREATE TABLE IF NOT EXISTS user_groups ( id INTEGER PRIMARY KEY, user_id INTEGER NOT NULL REFERENCES computer_users(id) ON DELETE CASCADE, name TEXT NOT NULL, UNIQUE (user_id, name) );",
    "CREATE TABLE IF NOT EXISTS vacancies ( id INTEGER PRIMARY KEY AUTOINCREMENT, network_id INTEGER NOT NULL REFERENCES networks(id) ON DELETE CASCADE, job_role INTEGER NOT NULL, computer_id INTEGER NOT NULL REFERENCES computers(id) ON DELETE CASCADE );",
    "CREATE TABLE IF NOT EXISTS wallet_balances ( id INTEGER PRIMARY KEY, wallet_id INTEGER NOT NULL REFERENCES wallets(id) ON DELETE CASCADE, coin_id INTEGER NOT NULL REFERENCES coins(id) ON DELETE CASCADE, amount REAL NOT NULL, UNIQUE (wallet_id, coin_id) );",
    "CREATE TABLE IF NOT EXISTS wallets ( id INTEGER PRIMARY KEY AUTOINCREMENT, user TEXT NOT NULL UNIQUE, password_hash TEXT NOT NULL REFERENCES passwords(hash), pin TEXT NOT NULL, bank_number TEXT NOT NULL REFERENCES bank_accounts(number), password_reset_at INTEGER );",
    "CREATE TABLE IF NOT EXISTS weakness_requirements ( id INTEGER PRIMARY KEY, weakness_id INTEGER NOT NULL REFERENCES weaknesses(id) ON DELETE CASCADE, requirement INTEGER NOT NULL, UNIQUE (weakness_id, requirement) );",
    "CREATE TABLE IF NOT EXISTS weaknesses ( id INTEGER PRIMARY KEY, zone_id INTEGER NOT NULL REFERENCES memory_zones(id) ON DELETE CASCADE, remote INTEGER NOT NULL, unsec_value TEXT NOT NULL, details TEXT NOT NULL, reward INTEGER NOT NULL, user TEXT NOT NULL, required_library INTEGER, required_version TEXT NOT NULL, metaxploit_version TEXT NOT NULL, num_register_users INTEGER NOT NULL, num_port_forward INTEGER NOT NULL, num_conn_gateway INTEGER NOT NULL, path_exist TEXT NOT NULL, random_path TEXT NOT NULL );",
    "CREATE UNIQUE INDEX IF NOT EXISTS networks_domain ON networks (domain) WHERE domain <> '';",
    "CREATE UNIQUE INDEX IF NOT EXISTS nodes_root ON nodes (computer_id) WHERE parent_id IS NULL;",
];

pub(super) const WORLD_META: &str = "CREATE TABLE IF NOT EXISTS world_meta ( id INTEGER PRIMARY KEY CHECK (id = 0), seed INTEGER NOT NULL, rng_state INTEGER NOT NULL, -- 0 once a game over deleted the player's computer (`Database.GameOver`) player_computer_id INTEGER NOT NULL, player_person_id INTEGER NOT NULL REFERENCES persons(id), elapsed_seconds INTEGER NOT NULL, clock_carry INTEGER NOT NULL, traffic_cooldown_until INTEGER, -- `InfoGen.WorldSecret`: what licence plates and the game's other derived values are keyed by. world_secret BLOB NOT NULL );";
